// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('delete_all_locked_no_deletion', async ({ page }) => {
    test.setTimeout(60000);

    const errors: Error[] = [];
    page.on('pageerror', (e) => errors.push(e));

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    // Wait for network activities to finish
    await page.waitForLoadState('networkidle');

    // Draw a rectangle
    await page.getByTestId("toolbar-rectangle").click();
    await page.mouse.move(400, 250);
    await page.mouse.down();
    await page.mouse.move(550, 350, { steps: 10 });
    await page.mouse.up();
    await page.waitForTimeout(500);

    // Right-click to open context menu and lock the element
    await page.locator("body").click({ button: "right", position: {"x": 475, "y": 300} });
    await page.waitForSelector('[data-testid="toggleElementLock"]');
    await page.getByTestId("toggleElementLock").getByRole('button', { name: 'Lock Ctrl+Shift+L' }).click();
    await page.waitForTimeout(300);

    // Press Delete — the locked element should NOT be deleted
    await page.keyboard.press("Delete");
    await page.waitForTimeout(500);

    // Assert that the Unlock button is still visible, confirming the locked element was preserved
    // The 'Unlock' button only appears when a locked element is selected — its presence
    // proves the element survived the Delete key press
    await expect(page.getByRole('generic', { name: 'Unlock' })).toBeVisible();

    // Assert no page errors occurred during the test
    expect(errors).toHaveLength(0);
});
